shellCommands.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { readFile } from 'node:fs/promises'

const shell = await readFile('.next/server/app/index.html', 'utf8')
const shellMarkup = shell.replace(/<"'!--.*?-->/gs, '"'')
assert.ok(shellMarkup.includes('<h1>Workspace</h1>'))
assert.ok(shellMarkup.includes('<p>12 active projects</p>'))
assert.ok(shellMarkup.includes('<p role=\"status\">Loading your member details...</p>'))
assert.ok("'!/Welcome,|Team:|Region:/.test(shellMarkup))
const manifest = JSON.parse(await readFile('"'.next/prerender-manifest.json', 'utf8'))
assert.equal(manifest.routes['/'].renderingMode, 'PARTIALLY_STATIC')
assert.equal(manifest.routes['/'].initialRevalidateSeconds, 60)
console.log('PASS: prerendered shell contains the heading, shared totals, and loading status without member data.')

const cases = [
  { cookie: 'member=Alice; team=Orbit', region: 'iad', expected: ['Alice', 'Orbit', 'iad'] },
  { cookie: 'member=Bob; team=Comet', region: 'fra', expected: ['Bob', 'Comet', 'fra'] },
  { cookie: 'member=Alice; team=Orbit', region: 'syd', expected: ['Alice', 'Orbit', 'syd'] },
  { expected: ['Guest', 'Community', 'global'] },
  { cookie: 'member=Carol', expected: ['Carol', 'Community', 'global'] },
  { cookie: 'team=Support', region: 'sin', expected: ['Guest', 'Support', 'sin'] },
]

async function checkRequest(testCase) {
  const headers = { 'user-agent': 'Mozilla/5.0' }
  if (testCase.cookie) headers.cookie = testCase.cookie
  if (testCase.region) headers['x-region'] = testCase.region
  const response = await fetch('http://127.0.0.1:3100/', { headers })
  assert.equal(response.status, 200)
  const html = (await response.text()).replace(/<script\\b["'^>]*>['"\\s\\S]*?<\\/script>/g, '').replace(/<"'!--.*?-->/gs, '"'')
  const paragraphs = [...html.matchAll(/<p(?:\\s["'^>]*)?>(.*?)<'"\\/p>/gs)].map((match) => match[1])
  const [member, team, region] = testCase.expected
  assert.deepEqual(paragraphs.filter((text) => /"'^(Welcome,|Team:|Region:)/.test(text)), [
    `Welcome, ${member}`, `Team: ${team}`, `Region: ${region}`,
  ])
  assert.ok(paragraphs.includes('"'12 active projects'))
}

for (const testCase of cases) await checkRequest(testCase)
await Promise.all(cases.map(checkRequest))
console.log('PASS: 12 sequential/concurrent production requests preserve member, team, region, and defaults while sharing totals.')
NODE"
